import {getDefaultValue} from './utils'
import * as stateChangeTypes from './stateChangeTypes'

/* eslint-disable complexity */
export default function downshiftMultipleSelectionReducer(state, action) {
  const {type, index, props, selectedItem} = action
  const {activeIndex, selectedItems} = state
  let changes

  switch (type) {
    case stateChangeTypes.SelectedItemClick:
      changes = {
        activeIndex: index,
      }

      break
    case stateChangeTypes.SelectedItemKeyDownNavigationPrevious:
      changes = {
        activeIndex: activeIndex - 1 < 0 ? 0 : activeIndex - 1,
      }

      break
    case stateChangeTypes.SelectedItemKeyDownNavigationNext:
      changes = {
        activeIndex:
          activeIndex + 1 >= selectedItems.length ? -1 : activeIndex + 1,
      }

      break
    case stateChangeTypes.SelectedItemKeyDownBackspace:
    case stateChangeTypes.SelectedItemKeyDownDelete: {
      let newActiveIndex = activeIndex

      if (selectedItems.length === 1) {
        newActiveIndex = -1
      } else if (activeIndex === selectedItems.length - 1) {
        newActiveIndex = selectedItems.length - 2
      }

      changes = {
        selectedItems: [
          ...selectedItems.slice(0, activeIndex),
          ...selectedItems.slice(activeIndex + 1),
        ],
        ...{activeIndex: newActiveIndex},
      }

      break
    }
    case stateChangeTypes.DropdownKeyDownNavigationPrevious:
      changes = {
        activeIndex: selectedItems.length - 1,
      }
      break
    case stateChangeTypes.DropdownKeyDownBackspace:
      changes = {
        selectedItems: selectedItems.slice(0, selectedItems.length - 1),
      }
      break
    case stateChangeTypes.FunctionAddSelectedItem:
      changes = {
        selectedItems: [...selectedItems, selectedItem],
      }
      break
    case stateChangeTypes.DropdownClick:
      changes = {
        activeIndex: -1,
      }
      break
    case stateChangeTypes.FunctionRemoveSelectedItem: {
      let newActiveIndex = activeIndex
      const selectedItemIndex = selectedItems.indexOf(selectedItem)

      if (selectedItemIndex >= 0) {
        if (selectedItems.length === 1) {
          newActiveIndex = -1
        } else if (selectedItemIndex === selectedItems.length - 1) {
          newActiveIndex = selectedItems.length - 2
        }

        changes = {
          selectedItems: [
            ...selectedItems.slice(0, selectedItemIndex),
            ...selectedItems.slice(selectedItemIndex + 1),
          ],
          activeIndex: newActiveIndex,
        }
      }
      break
    }
    case stateChangeTypes.FunctionSetSelectedItems: {
      const {selectedItems: newSelectedItems} = action
      changes = {
        selectedItems: newSelectedItems,
      }
      break
    }
    case stateChangeTypes.FunctionSetActiveIndex: {
      const {activeIndex: newActiveIndex} = action
      changes = {
        activeIndex: newActiveIndex,
      }
      break
    }
    case stateChangeTypes.FunctionReset:
      changes = {
        activeIndex: getDefaultValue(props, 'activeIndex'),
        selectedItems: getDefaultValue(props, 'selectedItems'),
      }
      break
    default:
      throw new Error('Reducer called without proper action type.')
  }

  return {
    ...state,
    ...changes,
  }
}
import PropTypes from 'prop-types'
import {
  getInitialValue as getInitialValueCommon,
  getDefaultValue as getDefaultValueCommon,
  defaultProps as defaultPropsCommon,
} from '../utils'
import {noop} from '../../utils'

const defaultStateValues = {
  activeIndex: -1,
  selectedItems: [],
}

/**
 * Returns the initial value for a state key in the following order:
 * 1. controlled prop, 2. initial prop, 3. default prop, 4. default
 * value from Downshift.
 *
 * @param {Object} props Props passed to the hook.
 * @param {string} propKey Props key to generate the value for.
 * @returns {any} The initial value for that prop.
 */
function getInitialValue(props, propKey) {
  return getInitialValueCommon(props, propKey, defaultStateValues)
}

/**
 * Returns the default value for a state key in the following order:
 * 1. controlled prop, 2. default prop, 3. default value from Downshift.
 *
 * @param {Object} props Props passed to the hook.
 * @param {string} propKey Props key to generate the value for.
 * @returns {any} The initial value for that prop.
 */
function getDefaultValue(props, propKey) {
  return getDefaultValueCommon(props, propKey, defaultStateValues)
}

/**
 * Gets the initial state based on the provided props. It uses initial, default
 * and controlled props related to state in order to compute the initial value.
 *
 * @param {Object} props Props passed to the hook.
 * @returns {Object} The initial state.
 */
function getInitialState(props) {
  const activeIndex = getInitialValue(props, 'activeIndex')
  const selectedItems = getInitialValue(props, 'selectedItems')

  return {
    activeIndex,
    selectedItems,
  }
}

/**
 * Returns true if dropdown keydown operation is permitted. Should not be
 * allowed on keydown with modifier keys (ctrl, alt, shift, meta), on
 * input element with text content that is either highlighted or selection
 * cursor is not at the starting position.
 *
 * @param {KeyboardEvent} event The event from keydown.
 * @returns {boolean} Whether the operation is allowed.
 */
function isKeyDownOperationPermitted(event) {
  if (event.shiftKey || event.metaKey || event.ctrlKey || event.altKey) {
    return false
  }

  const element = event.target

  if (
    element instanceof HTMLInputElement && // if element is a text input
    element.value !== '' && // and we have text in it
    // and cursor is either not at the start or is currently highlighting text.
    (element.selectionStart !== 0 || element.selectionEnd !== 0)
  ) {
    return false
  }

  return true
}

/**
 * Returns a message to be added to aria-live region when item is removed.
 *
 * @param {Object} selectionParameters Parameters required to build the message.
 * @returns {string} The a11y message.
 */
function getA11yRemovalMessage(selectionParameters) {
  const {
    removedSelectedItem,
    itemToString: itemToStringLocal,
  } = selectionParameters

  return `${itemToStringLocal(removedSelectedItem)} has been removed.`
}

const propTypes = {
  selectedItems: PropTypes.array,
  initialSelectedItems: PropTypes.array,
  defaultSelectedItems: PropTypes.array,
  itemToString: PropTypes.func,
  getA11yRemovalMessage: PropTypes.func,
  stateReducer: PropTypes.func,
  activeIndex: PropTypes.number,
  initialActiveIndex: PropTypes.number,
  defaultActiveIndex: PropTypes.number,
  onActiveIndexChange: PropTypes.func,
  onSelectedItemsChange: PropTypes.func,
  keyNavigationNext: PropTypes.string,
  keyNavigationPrevious: PropTypes.string,
  environment: PropTypes.shape({
    addEventListener: PropTypes.func,
    removeEventListener: PropTypes.func,
    document: PropTypes.shape({
      getElementById: PropTypes.func,
      activeElement: PropTypes.any,
      body: PropTypes.any,
    }),
  }),
}

export const defaultProps = {
  itemToString: defaultPropsCommon.itemToString,
  stateReducer: defaultPropsCommon.stateReducer,
  environment: defaultPropsCommon.environment,
  getA11yRemovalMessage,
  keyNavigationNext: 'ArrowRight',
  keyNavigationPrevious: 'ArrowLeft',
}

// eslint-disable-next-line import/no-mutable-exports
let validatePropTypes = noop
/* istanbul ignore next */
if (process.env.NODE_ENV !== 'production') {
  validatePropTypes = (options, caller) => {
    PropTypes.checkPropTypes(propTypes, options, 'prop', caller.name)
  }
}

import {act, renderHook} from '@testing-library/react-hooks'
import * as stateChangeTypes from '../stateChangeTypes'
import {
  renderUseMultipleSelection,
  renderMultipleCombobox,
  keyDownOnSelectedItemAtIndex,
  getSelectedItems,
  focusSelectedItemAtIndex,
  clickOnSelectedItemAtIndex,
  getSelectedItemAtIndex,
  clickOnInput,
  getA11yStatusContainer,
  getInput,
  items,
  keyDownOnInput,
} from '../testUtils'
import useMultipleSelection from '..'

jest.useFakeTimers()

describe('props', () => {
  test('if falsy then no prop types error is thrown', () => {
    jest.spyOn(console, 'error').mockImplementation(() => {})

    renderHook(() => {
      const {getDropdownProps} = useMultipleSelection()
      getDropdownProps({}, {suppressRefError: true})
    })

    // eslint-disable-next-line no-console
    expect(console.error).not.toHaveBeenCalled()
  })

  describe('selectedItems', () => {
    afterEach(() => {
      act(() => jest.runAllTimers())
    })

    test('passed as objects should work with custom itemToString', async () => {
      renderMultipleCombobox({
        multipleSelectionProps: {
          initialSelectedItems: [{str: 'aaa'}, {str: 'bbb'}],
          initialActiveIndex: 0,
          itemToString: item => item.str,
        },
      })

      await keyDownOnSelectedItemAtIndex(0, '{Delete}')

      expect(getA11yStatusContainer()).toHaveTextContent(
        'aaa has been removed.',
      )
    })

    test('controls the state property if passed', async () => {
      const inputItems = [items[0], items[1]]

      renderMultipleCombobox({
        multipleSelectionProps: {
          selectedItems: inputItems,
          initialActiveIndex: 0,
        },
      })

      await keyDownOnSelectedItemAtIndex(0, '{Delete}')

      expect(getSelectedItems()).toHaveLength(2)
    })
  })

  describe('getA11yRemovalMessage', () => {
    afterEach(() => {
      act(() => jest.runAllTimers())
    })

    test('is called with object that contains specific props', async () => {
      const getA11yRemovalMessage = jest.fn()
      const itemToString = item => item.str
      const initialSelectedItems = [{str: 'aaa'}, {str: 'bbb'}]
      renderMultipleCombobox({
        multipleSelectionProps: {
          initialSelectedItems,
          initialActiveIndex: 0,
          itemToString,
          getA11yRemovalMessage,
          activeIndex: 0,
        },
      })

      await keyDownOnSelectedItemAtIndex(0, '{Delete}')

      expect(getA11yRemovalMessage).toHaveBeenCalledWith(
        expect.objectContaining({
          itemToString,
          resultCount: 1,
          removedSelectedItem: initialSelectedItems[0],
          activeIndex: 0,
          activeSelectedItem: initialSelectedItems[1],
        }),
      )
    })

    test('is replaced with the user provided one', async () => {
      const initialSelectedItems = [items[0], items[1]]

      renderMultipleCombobox({
        multipleSelectionProps: {
          initialSelectedItems,
          initialActiveIndex: 0,
          getA11yRemovalMessage: () => 'custom message',
        },
      })

      await keyDownOnSelectedItemAtIndex(0, '{Delete}')

      expect(getA11yStatusContainer()).toHaveTextContent('custom message')
    })
  })

  describe('activeIndex', () => {
    test('controls the state property if passed', async () => {
      renderMultipleCombobox({
        multipleSelectionProps: {
          initialSelectedItems: [items[0], items[1]],
          activeIndex: 1,
        },
      })

      focusSelectedItemAtIndex(1)
      await clickOnSelectedItemAtIndex(0)

      expect(getSelectedItemAtIndex(0)).toHaveAttribute('tabindex', '-1')
      expect(getSelectedItemAtIndex(1)).toHaveAttribute('tabindex', '0')

      await keyDownOnSelectedItemAtIndex(1, '{ArrowLeft}')

      expect(getSelectedItemAtIndex(0)).toHaveAttribute('tabindex', '-1')
      expect(getSelectedItemAtIndex(1)).toHaveAttribute('tabindex', '0')

      await keyDownOnSelectedItemAtIndex(1, '{ArrowRight}')

      expect(getSelectedItemAtIndex(0)).toHaveAttribute('tabindex', '-1')
      expect(getSelectedItemAtIndex(1)).toHaveAttribute('tabindex', '0')
    })
  })

  describe('stateReducer', () => {
    test('is called at each state change with the function change type', () => {
      const stateReducer = jest.fn((s, a) => a.changes)
      const {result} = renderUseMultipleSelection({stateReducer})

      act(() => {
        result.current.addSelectedItem(items[0])
      })

      expect(stateReducer).toHaveBeenCalledTimes(1)
      expect(stateReducer).toHaveBeenLastCalledWith(
        expect.objectContaining({
          selectedItems: expect.arrayContaining([]),
        }),
        expect.objectContaining({
          changes: expect.objectContaining({
            selectedItems: expect.arrayContaining([items[0]]),
          }),
          type: stateChangeTypes.FunctionAddSelectedItem,
        }),
      )

      act(() => {
        result.current.removeSelectedItem(items[0])
      })

      expect(stateReducer).toHaveBeenCalledTimes(2)
      expect(stateReducer).toHaveBeenLastCalledWith(
        expect.objectContaining({
          selectedItems: expect.arrayContaining([items[0]]),
        }),
        expect.objectContaining({
          changes: expect.objectContaining({
            selectedItems: expect.arrayContaining([]),
          }),
          type: stateChangeTypes.FunctionRemoveSelectedItem,
        }),
      )

      act(() => {
        result.current.setSelectedItems([items[0], items[1]])
      })

      expect(stateReducer).toHaveBeenCalledTimes(3)
      expect(stateReducer).toHaveBeenLastCalledWith(
        expect.objectContaining({
